server {
    listen 8443 ssl http2;
    server_name localhost;

    ssl_certificate /etc/nginx/ssl/cert.crt;
    ssl_certificate_key /etc/nginx/ssl/key.key;

    ssl_protocols TLSv1.2 TLSv1.3;
    ssl_ciphers HIGH:!aNULL:!MD5;

    # Root location for main branch
    location = / {
        alias /var/www/main/;
        try_files /index.html =404;
    }

    location = /index.html {
        alias /var/www/main/index.html;
    }

    # Dev branch location
    location /dev/ {
        alias /var/www/dev/;
        try_files /index.html =404;
    }

    location /dev/index.html {
        alias /var/www/dev/index.html;
    }

    # Deny access to hidden files
    location ~ /\. {
        deny all;
    }

    error_log /var/log/nginx/git-deploy-error.log;
    access_log /var/log/nginx/git-deploy-access.log;
}

